commit a5dc5e2483b12c6971d49206c73f5350ab25f3b2
Author: Scott Densmore <scottdensmore@mac.com>
Date:   Tue Aug 4 07:41:59 2026 -0700

    wip(booking): drop the passenger seat columns

    INCOMPLETE — 8 test fixtures still assert the old shape. Not for merge.

    Production code compiles and the migration applies cleanly. What remains
    is test fixtures that build Passenger rows carrying a seat, a cabin and a
    flight, plus assertions on the booking result shape.

    Stopped here deliberately rather than leave a partially-corrected branch
    behind: main is green and every merged step is verified.

    Refs #137

    Entire-Checkpoint: 39e15153d731

diff --git a/prisma/migrations/20260804140000_drop_passenger_seat_columns/migration.sql b/prisma/migrations/20260804140000_drop_passenger_seat_columns/migration.sql
new file mode 100644
index 0000000..3e2e752
--- /dev/null
+++ b/prisma/migrations/20260804140000_drop_passenger_seat_columns/migration.sql
@@ -0,0 +1,43 @@
+-- Contract step for the traveller record (#137).
+--
+-- "Passenger" fused a traveller with a seat on one flight. A traveller is one
+-- person per booking; a seat is one per leg. Keeping both meant every reader
+-- had to be told which was authoritative, and four separate defects came from
+-- getting that wrong -- an outbound seat change overwriting the return seat
+-- (#126), return-leg occupancy answered from the outbound seat, a cabin layout
+-- change stranding a return-leg seat, and the admin manifest showing outbound
+-- seats on an inbound occurrence (#127).
+--
+-- Every reader moved to "SeatAssignment" in #127, and the last three fallbacks
+-- went in #146. Nothing reads these columns.
+--
+-- The invariant that made removing the fallbacks safe is checked again here
+-- rather than trusted: every traveller must hold an assignment on every leg of
+-- their booking. If that is false anywhere, this migration fails loudly instead
+-- of silently discarding the only record of where somebody sits.
+DO $$
+DECLARE
+    orphans bigint;
+BEGIN
+    SELECT count(*) INTO orphans
+    FROM "Passenger" p
+    JOIN "ItineraryLeg" l ON l."bookingId" = p."bookingId"
+    LEFT JOIN "SeatAssignment" sa
+        ON sa."passengerId" = p.id AND sa."legId" = l.id
+    WHERE sa.id IS NULL;
+
+    IF orphans > 0 THEN
+        RAISE EXCEPTION
+            'Refusing to drop Passenger seat columns: % passenger-legs have no SeatAssignment', orphans;
+    END IF;
+END $$;
+
+-- Dropping these removes "Passenger"'s unique seat index with them, leaving
+-- "SeatAssignment"'s UNIQUE (flightId, seatNumber) as the sole guard against
+-- two customers acquiring the same seat. That is the intended end state: both
+-- tables enforced it during the expand phase precisely so there was never a
+-- moment with no guard at all.
+ALTER TABLE "Passenger" DROP CONSTRAINT IF EXISTS "Passenger_flightId_fkey";
+ALTER TABLE "Passenger" DROP COLUMN "seatNumber";
+ALTER TABLE "Passenger" DROP COLUMN "cabinClass";
+ALTER TABLE "Passenger" DROP COLUMN "flightId";
/** @jest-environment node */
import fs from 'fs';
import path from 'path';
import { prisma } from '@/lib/prisma';

const migrationPath = path.resolve(
    process.cwd(),
    'prisma/migrations/20260801180000_add_seat_assignments/migration.sql'
);

/**
 * The backfill statement, taken from the migration rather than restated here,
 * scoped to one booking. Unscoped it would race other database test files that
 * create bookings concurrently.
 */
function backfillStatement(bookingId: number): string {
    const statement = fs.readFileSync(migrationPath, 'utf8')
        .split(';')
        .map(part => part
            .split(/\r?\n/)
            .filter(line => !line.trim().startsWith('--'))
            .join('\n')
            .trim())
        .find(part => part.startsWith('INSERT INTO "SeatAssignment"'));

    if (!statement) throw new Error('Backfill statement not found in the migration.');
    return `${statement} WHERE passenger."bookingId" = ${bookingId}`;
}

const created = { flightIds: [] as number[], bookingIds: [] as number[] };

async function createFlight(suffix: string) {
    const flight = await prisma.flight.create({
        data: {
            flightNumber: `SEAT-${suffix}`,
            airline: 'Gemini Airways',
            from: 'Seattle, USA',
            to: 'Detroit, USA',
            departureDate: new Date('2027-05-01T08:00:00Z'),
            priceCents: 35000,
        },
    });
    created.flightIds.push(flight.id);
    return flight;
}

/** A booking shaped the way one looked before seat assignments existed. */
async function createLegacyBooking(flightId: number, seatNumber: string) {
    const booking = await prisma.booking.create({
        data: {
            legs: { create: [{ sequence: 1, flightId }] },
            passengers: {
                create: [{
                    firstName: 'Ada',
                    lastName: 'Lovelace',
                    gender: 'Female',
                    seatNumber,
                    cabinClass: 'ECONOMY',
                    flightId,
                    // A traveller whose sensitive data has already been purged

